&lt;td&gt;即将出版&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;a href=&#34;https://gitee.com/luhuadong/YRPI&#34;&gt;YRPI&lt;/a&gt;&lt;/td&gt;
&lt;td&gt;基于树莓派的 Yocto 学习指南（reTerminal 树莓派 CM4）&lt;/td&gt;
&lt;td&gt;&lt;span class=&#34;github-emoji&#34; alias=&#34;star&#34; style=&#34;&#34; fallback-src=&#34;https://github.githubassets.com/images/icons/emoji/unicode/2b50.png?v8&#34;&gt;⭐&lt;/span&gt; &lt;span class=&#34;github-emoji&#34; alias=&#34;star&#34; style=&#34;&#34; fallback-src=&#34;https://github.githubassets.com/images/icons/emoji/unicode/2b50.png?v8&#34;&gt;⭐&lt;/span&gt; &lt;span class=&#34;github-emoji&#34; alias=&#34;star&#34; style=&#34;&#34; fallback-src=&#34;https://github.githubassets.com/images/icons/emoji/unicode/2b50.png?v8&#34;&gt;⭐&lt;/span&gt;&lt;/td&gt;
&lt;td&gt;进行中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
